#!/usr/bin/env python3
"""
Expands 22 topic instances from 10 → 50 exercises each.
Injects 40 new exercises per topic into the CORRECT files.
Also removes orphaned topic blocks from grade4/5/6 science.ts.
Difficulty spread target: 15 easy(1) + 20 medium(2) + 15 hard(3).
Existing 10: varies, so we add to reach totals.
"""

import re, os, sys

BASE = os.path.expanduser("~/projects/cleverli/src/data")

# ─── HELPERS ─────────────────────────────────────────────────────────────────

def q(s):
    return s.replace('"', '\\"')

def mc(id, diff, de, en, fr, it, ans, opts, h1, h2):
    o = '", "'.join(opts)
    return f'      {{ id: "{q(id)}", type: "multiple-choice", difficulty: {diff}, question: "{q(de)}", questionEN: "{q(en)}", questionFR: "{q(fr)}", questionIT: "{q(it)}", answer: "{q(ans)}", options: ["{o}"], hints: ["{q(h1)}", "{q(h2)}"] }},'

def fib(id, diff, de, en, fr, it, ans, h1, h2):
    return f'      {{ id: "{q(id)}", type: "fill-in-blank", difficulty: {diff}, question: "{q(de)}", questionEN: "{q(en)}", questionFR: "{q(fr)}", questionIT: "{q(it)}", answer: "{q(ans)}", hints: ["{q(h1)}", "{q(h2)}"] }},'

def dd(id, diff, de, en, fr, it, items, zones, answers, h1, h2):
    items_s = ", ".join(f'{{id:"{i}",label:"{q(l)}"}}' for i,l in items)
    zones_s = ", ".join(f'{{id:"{i}",label:"{q(l)}"}}' for i,l in zones)
    ans_s = ", ".join(f'"{k}":"{v}"' for k,v in answers.items())
    return f'      {{ id: "{q(id)}", type: "drag-drop", difficulty: {diff}, question: "{q(de)}", questionEN: "{q(en)}", questionFR: "{q(fr)}", questionIT: "{q(it)}", answer: "all", hints: ["{q(h1)}", "{q(h2)}"], dragItems: [{items_s}], dropZones: [{zones_s}], dropAnswers: {{{ans_s}}} }},'

def mt(id, diff, de, en, fr, it, pairs, h1, h2):
    pairs_s = ", ".join(f'{{id:"{pi}",label:"{q(pl)}",emoji:"{pe}"}}' for pi,pl,pe in pairs)
    return f'      {{ id: "{q(id)}", type: "matching", difficulty: {diff}, question: "{q(de)}", questionEN: "{q(en)}", questionFR: "{q(fr)}", questionIT: "{q(it)}", answer: "all", hints: ["{q(h1)}", "{q(h2)}"], pairs: [{pairs_s}] }},'

def mem(id, diff, de, en, fr, it, pairs, h1, h2):
    pairs_s = ", ".join(f'{{id:"{pi}",label:"{q(pl)}",emoji:"{pe}"}}' for pi,pl,pe in pairs)
    return f'      {{ id: "{q(id)}", type: "memory", difficulty: {diff}, question: "{q(de)}", questionEN: "{q(en)}", questionFR: "{q(fr)}", questionIT: "{q(it)}", answer: "all", hints: ["{q(h1)}", "{q(h2)}"], pairs: [{pairs_s}] }},'


# ─── INJECT FUNCTION ─────────────────────────────────────────────────────────

def inject_into_topic(filepath, topic_id, new_ts_lines):
    with open(filepath, encoding='utf-8') as f:
        content = f.read()
    
    pat = f'id: "{topic_id}"'
    pos = content.find(pat)
    if pos == -1:
        print(f"  ✗ Topic '{topic_id}' not found in {filepath}")
        return False
    
    exs_marker = 'exercises: ['
    exs_pos = content.find(exs_marker, pos)
    if exs_pos == -1:
        print(f"  ✗ exercises array not found for '{topic_id}'")
        return False
    
    depth = 0
    i = exs_pos + len(exs_marker)
    while i < len(content):
        c = content[i]
        if c == '[':
            depth += 1
        elif c == ']':
            if depth == 0:
                insert = '\n' + '\n'.join(new_ts_lines) + '\n'
                content = content[:i] + insert + content[i:]
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(content)
                print(f"  ✓ {topic_id} in {os.path.basename(filepath)}: +{len(new_ts_lines)} exercises")
                return True
            depth -= 1
        i += 1
    print(f"  ✗ Could not find closing bracket for '{topic_id}'")
    return False

def remove_topic(filepath, topic_id):
    with open(filepath, encoding='utf-8') as f:
        content = f.read()
    
    pat = f'    id: "{topic_id}",'
    pos = content.find(pat)
    if pos == -1:
        print(f"  – '{topic_id}' not found in {os.path.basename(filepath)} (already removed?)")
        return True
    
    block_start = content.rfind('  {', 0, pos)
    if block_start == -1:
        print(f"  ✗ Cannot find block start for '{topic_id}'")
        return False
    
    depth = 0
    i = block_start
    while i < len(content):
        c = content[i]
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                end = i + 1
                if end < len(content) and content[end] == ',':
                    end += 1
                if end < len(content) and content[end] == '\n':
                    end += 1
                content = content[:block_start] + content[end:]
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(content)
                print(f"  ✓ Removed '{topic_id}' from {os.path.basename(filepath)}")
                return True
        i += 1
    print(f"  ✗ Cannot find end of block for '{topic_id}'")
    return False

